/// <summary>
/// AVA_007871_CopySalesQuotationsSpanGroups
/// </summary>
/// <param name = "_set">boolean</param>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
/// <param name = "_copy">NoYes</param>
/// <returns>NoYes</returns>
edit NoYes  copy(boolean                _set,
                     SalesQuotationLine     _salesQuotationLine,
                     NoYes                  _copy)
{
    NoYes               ret = false;
    SalesQuotationLine  sqlSameLV;
    PdsCWInventQty      cwQty = 0;
    boolean             cwItem = false;

    ret = next Copy(_set, _salesQuotationLine, _copy);

    if (_salesQuotationLine.KCS_QLInternalPosition)
    {
        while select sqlSameLV where sqlSameLV.QuotationId == _salesQuotationLine.QuotationId
                                  && sqlSameLV.KCS_QLLVPosition == _salesQuotationLine.KCS_QLLVPosition
                                  && sqlSameLV.KCS_QLInternalPosition && sqlSameLV.KCS_QLInternalPosition != _salesQuotationLine.KCS_QLInternalPosition
        {
            if (PdsGlobal::pdsIsCWItem(sqlSameLV.ItemId))
            {
                cwItem = true;
                cwQty = sqlSameLV.PdsCWQty;
            }
            else
            {
                cwItem = false;
                cwQty = 0;
            }
            ret = element.editCopy(_set,
                                    sqlSameLV,
                                    sqlSameLV.QuotationId,
                                    sqlSameLV.LineNum,
                                    DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                    sqlSameLV.SalesQty,
                                    _copy,
                                    cwItem,
                                    cwQty);
        }
    }
    return ret;
}
